92	    .FIFO_DEPTH (1)
93	  )
94	  data_buffer (
95	    .clk       (clk                  ),
96	    .rst_n     (rst_n                ),
97	    .w_ready_o (in_ready_o           ),
98	    .w_valid_i (in_valid_i           ),
99	    .w_data_i  (data_buffer_enq_bits ),
