109	  wire [`DEPTH_WARP-1:0]                 data_buffer_wid     ;
110	  wire                                   data_buffer_fp      ;
111	  wire                                   data_buffer_reverse ;
112	  wire                                   data_buffer_isvec   ;
113	  wire [5:0]                             data_buffer_alu_fn  ;
114	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] data_buffer_reg_idxw;
115	  wire                                   data_buffer_wvd     ;
116	  wire                                   data_buffer_wxd     ;
117	  //wire [2:0]                             data_buffer_rm      ;
118	
119	  assign data_buffer_in1      = data_buffer_deq_bits[`XLEN*`NUM_THREAD*3+`NUM_THREAD+`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+13:`XLEN*`NUM_THREAD*2+`NUM_THREAD+`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+14];
120	  assign data_buffer_in2      = data_buffer_deq_bits[`XLEN*`NUM_THREAD*2+`NUM_THREAD+`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+13:`XLEN*`NUM_THREAD+`NUM_THREAD+`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+14];
121	  //assign data_buffer_in3      = data_buffer_deq_bits[`XLEN*`NUM_THREAD+`NUM_THREAD+`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+13:`NUM_THREAD+`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+14];
122	  assign data_buffer_mask     = data_buffer_deq_bits[`NUM_THREAD+`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+13:`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+14];
123	  assign data_buffer_wid      = data_buffer_deq_bits[`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+13:`REGIDX_WIDTH+`REGEXT_WIDTH+14];
124	  assign data_buffer_fp       = data_buffer_deq_bits[`REGIDX_WIDTH+`REGEXT_WIDTH+13];
125	  assign data_buffer_reverse  = data_buffer_deq_bits[`REGIDX_WIDTH+`REGEXT_WIDTH+12];
126	  assign data_buffer_isvec    = data_buffer_deq_bits[`REGIDX_WIDTH+`REGEXT_WIDTH+11];
127	  assign data_buffer_alu_fn   = data_buffer_deq_bits[`REGIDX_WIDTH+`REGEXT_WIDTH+10:`REGIDX_WIDTH+`REGEXT_WIDTH+5];
128	  assign data_buffer_reg_idxw = data_buffer_deq_bits[`REGIDX_WIDTH+`REGEXT_WIDTH+4:5];
129	  assign data_buffer_wvd      = data_buffer_deq_bits[4];
130	  assign data_buffer_wxd      = data_buffer_deq_bits[3];
