134	  wire [NUM_GRP-1:0]     mask_grp ;
135	  wire [`NUM_THREAD-1:0] next_mask;
136	  wire                   o_ready  ;
137	
138	  genvar i;
139	  generate for(i=0;i<NUM_GRP;i=i+1) begin: MASK_GRP_GEN
140	    assign mask_grp[i] = |mask[`NUM_SFU*(i+1)-1:`NUM_SFU*i];
141	  end
142	  endgenerate
143	
144	  //initialize the reg(out_data), and cat it
145	  reg  [`XLEN*`NUM_THREAD-1:0] out_data     ;
146	  wire [`XLEN*`NUM_SFU-1:0]    arb_out_cat  ;
147	  wire [NUM_GRP-1:0]           mask_grp_oh  ;
148	  wire [$clog2(NUM_GRP)-1:0]   i_cnt        ;
149	  wire                         sfu_out_fire ;
150	
151	  wire [`XLEN-1:0]  arb_out   [0:`NUM_SFU-1];
152	  
153	  genvar k;
154	  generate for(k=0;k<NUM_GRP;k=k+1) begin: INIT_OUT_DATA
155	    always@(posedge clk or negedge rst_n) begin
156	      if(!rst_n) begin
157	        out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k] <= 'd0;
158	      end
159	      else if((c_state==S_FINISH) && o_ready) begin
160	        out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k] <= 'd0;
161	      end
162	      else if(c_state==S_BUSY) begin
163	        if(data_buffer_isvec && sfu_out_fire) begin
164	          if(!(|mask)) begin
165	            out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k] <= out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k];
166	          end
167	          else begin
168	            out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k] <= (k==i_cnt) ? arb_out_cat : out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k];
169	          end
170	        end
171	        else if(sfu_out_fire) begin
172	          out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k] <= (k=='d0) ? {out_data[`XLEN*`NUM_SFU*(k+1)-1 -:`XLEN],arb_out[0]} : out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k];
173	        end
174	        else begin
175	          out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k] <= out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k];
176	        end
177	      end
178	      else begin
179	        out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k] <= out_data[`XLEN*`NUM_SFU*(k+1)-1:`XLEN*`NUM_SFU*k];
180	      end
181	    end
182	  end
183	  endgenerate
184	
185	  //wire [NUM_GRP-1:0]         mask_grp_oh;
186	  //wire [$clog2(NUM_GRP)-1:0] i_cnt      ;
187	  
188	  fixed_pri_arb #(
189	    .ARB_WIDTH (NUM_GRP)
190	  )
191	  mask_grp_pri_oh (
192	    .req   (mask_grp   ),
193	    .grant (mask_grp_oh)
194	  );
195	
196	  one2bin #(
197	    .ONE_WIDTH (NUM_GRP        ),
198	    .BIN_WIDTH ($clog2(NUM_GRP))
199	  )
200	  mask_grp_pri_bin (
201	    .oh  (mask_grp_oh),
202	    .bin (i_cnt      )
203	  );
