205	  reg                                    i_valid   ;
206	  wire [`DEPTH_WARP-1:0]                 i_wid     ;
207	  wire                                   i_fp      ;
208	  wire                                   i_reverse ;
209	  wire                                   i_isvec   ;
210	  wire [5:0]                             i_alu_fn  ;
211	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] i_reg_idxw;
212	  wire                                   i_wvd     ;
213	  wire                                   i_wxd     ;
214	  wire [`XLEN*`NUM_SFU-1:0]              i_data_1  ;
215	  wire [`XLEN*`NUM_SFU-1:0]              i_data_2  ;
216	  //wire [`XLEN*`NUM_SFU-1:0]              i_data_3  ;
217	  //wire [`NUM_SFU-1:0]                    i_mask    ;
218	  wire [`XLEN*`NUM_SFU-1:0]              i_1       ;
219	  wire [`XLEN*`NUM_SFU-1:0]              i_2       ;
220	
