222	  assign i_fp       = data_buffer_fp      ;
223	  assign i_reverse  = data_buffer_reverse ;
224	  assign i_isvec    = data_buffer_isvec   ;
225	  assign i_alu_fn   = data_buffer_alu_fn  ;
226	  assign i_reg_idxw = data_buffer_reg_idxw;
227	  assign i_wvd      = data_buffer_wvd     ;
228	  assign i_wxd      = data_buffer_wxd     ;
229	
