231	  assign i_2      = data_buffer_in2[`NUM_SFU*`XLEN*(i_cnt+1)-1 -:`NUM_SFU*`XLEN];
232	  assign i_data_1 = i_reverse ? i_2 : i_1                                       ;
233	  assign i_data_2 = i_reverse ? i_1 : i_2                                       ;
234	  //assign i_data_3 = data_buffer_in3[`NUM_SFU*`XLEN*(i_cnt+1)-1 -:`NUM_SFU*`XLEN];
235	  //assign i_mask   = mask[`NUM_SFU*(i_cnt+1)-1 -:`NUM_SFU]                       ;
