237	  genvar j;
238	  generate for(j=0;j<NUM_GRP;j=j+1) begin: I_DATA
239	    always@(*) begin
240	      if(j==i_cnt) begin
241	        i_1      = data_buffer_in1[`NUM_SFU*`XLEN*(j+1)-1:`NUM_SFU*`XLEN*j];
242	        i_2      = data_buffer_in2[`NUM_SFU*`XLEN*(j+1)-1:`NUM_SFU*`XLEN*j];
243	        i_data_1 = i_reverse ? i_2 : i_1                                   ;
244	        i_data_2 = i_reverse ? i_1 : i_2                                   ;
245	        i_data_3 = data_buffer_in3[`NUM_SFU*`XLEN*(j+1)-1:`NUM_SFU*`XLEN*j];
246	        i_mask   = mask[`NUM_SFU*(j+1)-1:`NUM_SFU*j]                       ;
247	      end
248	    end
249	  end
250	  endgenerate
251	  */
