289	  wire                arb_in_ready_1 [0:`NUM_SFU-1];
290	  //wire [`XLEN-1:0]    arb_out        [0:`NUM_SFU-1];
291	  wire                arb_out_valid  [0:`NUM_SFU-1];
292	  wire                arb_out_ready  [0:`NUM_SFU-1];
293	  wire [`NUM_SFU-1:0] arb_out_valid_cat            ;
294	  
295	  //result_v, result_x
296	  wire                                   result_x_enq_valid;
297	  wire                                   result_x_enq_ready;
298	  wire                                   result_x_deq_valid;
