310	  wire                                   result_v_deq_ready;
311	  wire [`DEPTH_WARP-1:0]                 result_v_warp_id  ;
312	  wire                                   result_v_wvd      ;
313	  wire [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0] result_v_reg_idxw ;
314	  wire [`NUM_THREAD-1:0]                 result_v_wvd_mask ;
