355	    .DATA_WIDTH (`DEPTH_WARP+`REGIDX_WIDTH+`REGEXT_WIDTH+`NUM_THREAD+`XLEN*`NUM_THREAD+1),
356	    .FIFO_DEPTH (1)
357	  )
358	  result_v (
359	    .clk       (clk               ),
360	    .rst_n     (rst_n             ),
361	    .w_ready_o (result_v_enq_ready),
362	    .w_valid_i (result_v_enq_valid),
363	    .w_data_i  (result_v_enq_bits ),
