380	  //module: inv_div, float_sqrt_div(`NUM_SFU)
381	  genvar n;
382	  generate for(n=0;n<`NUM_SFU;n=n+1) begin: CONNECTION
383	    assign arb_out_valid_cat[n] = arb_out_valid[n]                            ;
384	    assign arb_out_ready[n]     = &arb_out_valid_cat                          ;
385	
386	    assign intdiv_a[n]          = i_data_1[`XLEN*(n+1)-1:`XLEN*n]             ;
387	    assign intdiv_d[n]          = i_data_2[`XLEN*(n+1)-1:`XLEN*n]             ;
388	    assign intdiv_sign_bit[n]   = !i_alu_fn[1]                                ;
389	    assign intdiv_in_valid[n]   = !i_fp && i_valid                            ;
390	    assign intdiv_out_ready[n]  = arb_in_ready_0[n]                           ;
391	
392	    assign float_in_valid[n]    = i_fp && i_valid                             ;
393	    assign float_div_start[n]   = float_in_valid[n] && (i_alu_fn[2:0] == 'd0 );
394	    assign float_sqrt_start[n]  = float_in_valid[n] && (i_alu_fn[2:0] != 'd0) ;
395	    assign float_in_ready[n]    = float_ready_s0[n] && !float_done_s0[n]      ;
396	    assign float_out_valid[n]   = float_done_s0[n] || float_done_reg[n]       ;
397	    assign float_out_ready[n]   = arb_in_ready_1[n]                           ;
398	    assign float_in_a[n]        = i_data_1[`XLEN*(n+1)-1:`XLEN*n]             ;
399	    assign float_in_b[n]        = i_data_2[`XLEN*(n+1)-1:`XLEN*n]             ;
400	    assign float_in_rm[n]       = in_rm_i                                     ;
401	    assign float_out_result[n]  = float_done_s0[n] ? float_result[n] : float_result_reg[`NUM_SFU*(n+1)-1:`NUM_SFU*n];
402	    //assign float_out_fflags[n]  = float_done_s0[n] ? float_fflags[n] : float_fflags_reg[`NUM_SFU*(n+1)-1:`NUM_SFU*n];
403	
404	    always@(posedge clk or negedge rst_n) begin
405	      if(!rst_n) begin
406	        float_done_reg[n] <= 'd0;
407	      end
408	      else begin
409	        if(float_out_valid[n] && float_out_ready[n]) begin
410	          float_done_reg[n] <= 'd0;
411	        end
412	        else begin
413	          float_done_reg[n] <= float_done_s0[n] || float_done_reg[n];
414	        end
415	      end
416	    end
417	
418	    always@(posedge clk or negedge rst_n) begin
419	      if(!rst_n) begin
420	        float_result_reg[(EXPWIDTH+PRECISION)*(n+1)-1:(EXPWIDTH+PRECISION)*n] <= 'd0;
421	        float_fflags_reg[5*(n+1)-1:5*n] <= 'd0;
422	      end
423	      else begin
424	        if(float_done_s0) begin
425	          float_result_reg[(EXPWIDTH+PRECISION)*(n+1)-1:(EXPWIDTH+PRECISION)*n] <= float_result[n];
426	          float_fflags_reg[5*(n+1)-1:5*n] <= float_fflags[n];
427	        end
428	        else begin
429	          float_result_reg[(EXPWIDTH+PRECISION)*(n+1)-1:(EXPWIDTH+PRECISION)*n] <= float_result_reg[(EXPWIDTH+PRECISION)*(n+1)-1:(EXPWIDTH+PRECISION)*n];
430	          float_fflags_reg[5*(n+1)-1:5*n] <= float_fflags_reg[5*(n+1)-1:5*n];
431	        end
432	      end
433	    end
434	 
435	    int_div invdiv( 
436	      .clk         (clk                ),
437	      .rst_n       (rst_n              ),
438	      .a_i         (intdiv_a[n]        ),
439	      .d_i         (intdiv_d[n]        ),
440	      .sign_bit    (intdiv_sign_bit[n] ),
441	      .in_valid_i  (intdiv_in_valid[n] ),
442	      .out_ready_i (intdiv_out_ready[n]),
443	      .in_ready_o  (intdiv_in_ready[n] ),
444	      .out_valid_o (intdiv_out_valid[n]),
445	      .q_o         (intdiv_q[n]        ),
446	      .r_o         (intdiv_r[n]        )
447	    );
448	
449	    div_sqrt_top_mvp flaot_div_sqrt(
450	      .Clk_CI           (clk                                ),
451	      .Rst_RBI          (rst_n                              ),
452	      .Div_start_SI     (float_div_start[n]                 ),
453	      .Sqrt_start_SI    (float_sqrt_start[n]                ),
454	      .Operand_a_DI     ({32'h0,float_in_a[n]}              ),
455	      .Operand_b_DI     ({32'h0,float_in_b[n]}              ),
456	      .RM_SI            (float_in_rm[n]                     ),
457	      .Precision_ctl_SI (6'h00                              ), //full precision
458	      .Format_sel_SI    (2'b00                              ), //FP32
459	      .Kill_SI          (1'b0                               ),
460	      .Result_DO        ({unused_reasult[n],float_result[n]}),
461	      .Fflags_SO        (float_fflags[n]                    ),
462	      .Ready_SO         (float_ready_s0[n]                  ),
463	      .Done_SO          (float_done_s0[n]                   )
464	    );
465	    
466	    assign arb_in_0[n]       = i_alu_fn[0] ? intdiv_r[n] : intdiv_q[n]      ;
467	    assign arb_in_1[n]       = float_out_result[n]                          ;
468	    assign arb_in_valid_0[n] = intdiv_out_valid[n]                          ;
469	    assign arb_in_valid_1[n] = float_out_valid[n]                           ;
470	    assign arb_out_valid[n]  = arb_in_valid_0[n] || arb_in_valid_1[n]       ;
471	    assign arb_in_ready_0[n] = arb_out_ready[n]                             ;
472	    assign arb_in_ready_1[n] = arb_out_ready[n] && !arb_in_valid_0[n]       ;
473	    assign arb_out[n]        = arb_in_valid_0[n] ? arb_in_0[n] : arb_in_1[n];
474	    assign arb_out_cat[`XLEN*(n+1)-1:`XLEN*n] = arb_out[n]                  ;
475	  end
476	  endgenerate
477	
478	  wire i_ready         ;
479	  //wire sfu_out_fire    ;
480	
481	  assign i_ready               = i_fp ? float_in_ready[0] : intdiv_in_ready[0];
482	  assign data_buffer_deq_ready = (c_state==S_FINISH) && o_ready               ;
483	  assign sfu_out_fire          = arb_out_valid[0] && arb_out_ready[0]         ;
484	
485	  //fsm
486	  always@(posedge clk or negedge rst_n) begin
487	    if(!rst_n) begin
488	      c_state <= 'd0;
489	    end
490	    else begin
491	      c_state <= n_state;
492	    end
493	  end
494	
495	  always@(*) begin
496	    case(c_state)
497	      S_IDLE  : begin
498	        if(in_valid_i && in_ready_o) begin
499	          n_state = S_BUSY;
500	        end
501	        else begin
502	          n_state = S_IDLE;
503	        end
504	      end
505	      S_BUSY  : begin
506	        if(data_buffer_isvec && sfu_out_fire) begin
507	          if(!(|next_mask)) begin
508	            n_state = S_FINISH;
509	          end
510	          else begin
511	            n_state = S_BUSY;
512	          end
513	        end
514	        else if(sfu_out_fire) begin
515	          n_state = S_FINISH;
516	        end
517	        else begin
518	          n_state = S_BUSY;
519	        end
520	      end
521	      S_FINISH: begin
522	        if(o_ready) begin
523	          n_state = S_IDLE;
524	        end
525	        else begin
526	          n_state = S_FINISH;
527	        end
528	      end
529	      default : begin
530	        n_state = S_IDLE;
531	      end
532	    endcase
533	  end
534	
535	  //fsm operations
536	  assign next_mask = mask & {{(`NUM_THREAD-`NUM_SFU){1'b1}},{`NUM_SFU{1'b0}}} << (i_cnt*`NUM_SFU);
537	
538	  always@(posedge clk or negedge rst_n) begin
539	    if(!rst_n) begin
540	      i_valid <= 'd0;
541	      mask    <= 'd0;
542	    end
543	    else begin
544	      case(c_state)
545	        S_IDLE  : begin
546	          if(in_valid_i && in_ready_o) begin
547	            i_valid <= 1'b1     ;
548	            mask    <= in_mask_i;
549	          end
550	          else begin
551	            i_valid <= 'd0;
552	            mask    <= 'd0;
553	          end
554	        end
555	        S_BUSY  : begin
556	          if(data_buffer_isvec && sfu_out_fire) begin
557	            if(!(|mask)) begin
558	              i_valid <= 'd0;
559	            end
560	            else begin
561	              i_valid                    <= (|next_mask) ? 1'b1 : 1'b0;
562	              mask                       <= next_mask                 ;
563	            end
564	          end
565	          else if(sfu_out_fire) begin
566	            i_valid     <= 'd0       ;
567	          end
568	          else if(i_valid && i_ready) begin
569	            i_valid <= 'd0;
570	          end
571	          else begin
572	            i_valid <= i_valid;
573	            mask    <= mask   ;
574	          end
575	        end
576	        default : begin
577	          i_valid <= i_valid;
578	          mask    <= mask   ;
579	        end
580	      endcase
581	    end
582	  end
583	
584	  //outputs
585	  assign out_x_valid_o     = result_x_deq_valid;
586	  assign out_x_warp_id_o   = result_x_warp_id  ;
587	  assign out_x_wxd_o       = result_x_wxd      ;
588	  assign out_x_reg_idxw_o  = result_x_reg_idxw ;
589	  assign out_x_wb_wxd_rd_o = result_x_wb_wxd_rd;
590	                                                
591	  assign out_v_valid_o     = result_v_deq_valid;
592	  assign out_v_warp_id_o   = result_v_warp_id  ;
593	  assign out_v_wvd_o       = result_v_wvd      ;
594	  assign out_v_reg_idxw_o  = result_v_reg_idxw ;
595	  assign out_v_wvd_mask_o  = result_v_wvd_mask ;
596	  assign out_v_wb_wvd_rd_o = result_v_wb_wvd_rd;
597	                                                
598	endmodule
599	
