7	 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND,
8	 * EITHER EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT,
9	 * MERCHANTABILITY OR FIT FOR A PARTICULAR PURPOSE.
10	 * See the Mulan PSL v2 for more details. */
11	// Author: Gu, Zihan
12	// Description:integer division
13	`timescale 1ns/1ns
14	`include "define.v"
15	module int_div(
16	  input                                   clk        ,
17	  input                                   rst_n      ,
18	
19	  input   [`XLEN-1:0]                     a_i        ,//被除数dividend
20	  input   [`XLEN-1:0]                     d_i        ,//除数divisor
21	  input                                   sign_bit   ,
22	
23	  input                                   in_valid_i ,
24	  input                                   out_ready_i,
25	
26	  output                                  in_ready_o ,
27	  output                                  out_valid_o,
28	
29	  output  [`XLEN-1:0]                     q_o        ,//商quotient
30	  output  [`XLEN-1:0]                     r_o         //余数remainder
31	  );
32	  parameter IDLE     = 3'b000;
33	  parameter PRE      = 3'b001;
34	  parameter COMPUTE  = 3'b010;
35	  parameter RECOVERY = 3'b011;
36	  parameter FINISH   = 3'b100;
37	
38	  reg [2:0] current_state;
39	  reg [2:0] next_state;
40	
41	  wire                                    a_sign         ;
42	  wire                                    d_sign         ;
43	  reg                                     q_sign_reg     ;
44	  reg                                     r_sign_reg     ;
45	  wire  [`XLEN-1:0]                       unsigned_a     ;
46	  wire  [`XLEN-1:0]                       unsigned_d     ;
47	  wire  [`XLEN-2:0]                       a_without_sign ;
48	  wire                                    overflow       ;
49	  wire                                    div_by_zero    ;
50	  reg   [`XLEN-1:0]                       raw_a_reg      ;
51	  reg   [`XLEN-1:0]                       unsigned_a_reg ;
52	  reg   [`XLEN-1:0]                       unsigned_d_reg ;
53	  reg                                     overflow_reg   ;
54	  reg                                     div_by_zero_reg;
55	
56	  //pre phase
57	  wire  [$clog2(`XLEN)-1:0]               a_lez     ;
58	  wire  [$clog2(`XLEN)-1:0]               d_lez     ;
59	  wire  [$clog2(`XLEN)-1:0]               iter      ;
60	  reg   [`XLEN+1:0]                       a_reg     ;
61	  reg   [`XLEN+1:0]                       d_reg     ;
62	  wire  [`XLEN+1:0]                       a_norm    ;
63	  wire  [`XLEN+1:0]                       d_norm    ;
64	  wire  [`XLEN+1:0]                       d_neg_norm;
65	  reg   [$clog2(`XLEN)-1:0]               iter_reg  ;
66	  reg                                     zero_q_reg;
67	
68	  //compute phase
69	  reg   [$clog2(`XLEN+1)-1:0]             cnt       ;
70	  reg   [$clog2(`XLEN+1)-1:0]             cnt_next  ;
71	  reg   [`XLEN-1:0]                       q         ;
72	  reg   [`XLEN-1:0]                       qn        ;
73	  wire                                    sel_pos   ;
74	  wire                                    sel_neg   ;
75	  wire  [`XLEN+1:0]                       a_shift   ;
76	  wire  [`XLEN+1:0]                       a_next    ;
77	
78	  //recovery phase
79	  wire                                    rem_is_neg  ;
80	  wire  [`XLEN-1:0]                       common_q    ;
81	  wire  [`XLEN-1:0]                       common_r    ;
82	  reg   [`XLEN-1:0]                       common_q_reg;
83	  reg   [`XLEN-1:0]                       common_r_reg;
84	  wire  [`XLEN-1:0]                       recovery_r  ;
85	
86	  //finish phase
87	  wire  [`XLEN-1:0]                       signed_q    ;
88	  wire  [`XLEN-1:0]                       signed_r    ;
89	  wire  [`XLEN-1:0]                       special_q   ;
90	  wire  [`XLEN-1:0]                       special_r   ;
91	  
92	  assign  a_sign         = sign_bit & a_i[`XLEN-1];
93	  assign  d_sign         = sign_bit & d_i[`XLEN-1];
94	  assign  unsigned_a     = a_sign ? (~a_i+1) : a_i;
95	  assign  unsigned_d     = d_sign ? (~d_i+1) : d_i;
96	  assign  a_without_sign = a_i[`XLEN-2:0];
97	  assign  overflow       = sign_bit & a_i[`XLEN-1] & !(|a_without_sign) & (&d_i);
98	  assign  div_by_zero    = d_i == 'd0;
99	
100	  //状态跳转
101	  always@(posedge clk or negedge rst_n) begin
102	    if(!rst_n) begin
103	      current_state <= IDLE;
104	    end
105	    else begin
106	      current_state <= next_state;
107	    end
108	  end
109	
110	  //商和余数的符号
111	  always@(posedge clk or negedge rst_n) begin
112	    if(!rst_n) begin
113	      q_sign_reg      <= 'd0;
114	      r_sign_reg      <= 'd0;
115	      raw_a_reg       <= 'd0;
116	      unsigned_a_reg  <= 'd0;
117	      unsigned_d_reg  <= 'd0;
118	      overflow_reg    <= 'd0;
119	      div_by_zero_reg <= 'd0;
120	    end
121	    else if(in_valid_i & in_ready_o) begin
122	      q_sign_reg      <= a_sign ^ d_sign;
123	      r_sign_reg      <= a_sign         ;
124	      raw_a_reg       <= a_i            ;
125	      unsigned_a_reg  <= unsigned_a     ;
126	      unsigned_d_reg  <= unsigned_d     ;
127	      overflow_reg    <= overflow       ;
128	      div_by_zero_reg <= div_by_zero    ;
129	    end
130	    else begin
131	      q_sign_reg      <= q_sign_reg     ;
132	      r_sign_reg      <= r_sign_reg     ;
133	      raw_a_reg       <= raw_a_reg      ;
134	      unsigned_a_reg  <= unsigned_a_reg ;
135	      unsigned_d_reg  <= unsigned_d_reg ;
136	      overflow_reg    <= overflow_reg   ;
137	      div_by_zero_reg <= div_by_zero_reg;
138	    end
139	  end
140	
141	  //pre phase
142	  find_first #(.DATA_WIDTH(`XLEN),
143	               .DATA_DEPTH($clog2(`XLEN)))
144	               U_find_first_a(
145	                              .data_i(unsigned_a_reg),
146	                              .target(1'b1          ),
147	                              .data_o(a_lez         )
148	                             );
149	
150	  find_first #(.DATA_WIDTH(`XLEN),
151	               .DATA_DEPTH($clog2(`XLEN)))
152	               U_find_first_d(
153	                              .data_i(unsigned_d_reg),
154	                              .target(1'b1          ),
155	                              .data_o(d_lez         )
156	                             );
157	
158	  assign  iter       = (a_lez > d_lez) ? 'd0 : (d_lez - a_lez + 1);
159	  assign  a_norm     = {2'd0,(unsigned_a_reg<<a_lez)};
160	  assign  d_norm     = {1'b0,(unsigned_d_reg<<d_lez),1'b0};
161	  assign  d_neg_norm = {1'b1,((~unsigned_d_reg+1)<<d_lez),1'b0};
162	
163	  always@(posedge clk or negedge rst_n) begin
164	    if(!rst_n) begin
165	      iter_reg   <= 'd0;
166	      zero_q_reg <= 'd0;
167	    end
168	    else if(current_state == PRE) begin
169	      iter_reg   <= iter                             ;
170	      zero_q_reg <= (unsigned_a_reg < unsigned_d_reg);
171	    end
172	    else begin
173	      iter_reg   <= iter_reg  ;
174	      zero_q_reg <= zero_q_reg;
175	    end
176	  end
177	
178	  //compute phase
179	  //assign  cnt_next = (cnt == 'd0) ? 'd0 : (cnt - 1);
180	  always@(*) begin
181	   if(cnt == 'd0) begin
182	    cnt_next = 'd0;
183	   end
184	   else begin
185	    cnt_next = cnt - 1;
186	   end
187	  end
188	  
189	  assign  sel_pos  = a_reg[`XLEN:`XLEN-1] == 2'b01;
190	  assign  sel_neg  = a_reg[`XLEN:`XLEN-1] == 2'b10;
191	  assign  a_shift  = a_reg << 1;
192	  assign  a_next   = sel_pos ? a_shift + d_neg_norm : (sel_neg ? (a_shift + d_norm) : a_shift);
193	
194	  //recovery phase
195	  assign  rem_is_neg = a_reg[`XLEN+1];
196	  assign  recovery_r = rem_is_neg ? a_reg[`XLEN:1] + d_reg[`XLEN:1] : a_reg[`XLEN:1];
197	  assign  common_q   = rem_is_neg ? (q + ~qn) : (q - qn);
198	  assign  common_r   = recovery_r >> d_lez;
199	
200	  always@(posedge clk or negedge rst_n) begin
201	    if(!rst_n) begin
202	      common_q_reg <= 'd0;
203	      common_r_reg <= 'd0;
204	    end
205	    else if(current_state == RECOVERY) begin
206	      common_q_reg <= common_q;
207	      common_r_reg <= common_r;
208	    end
209	    else begin
210	      common_q_reg <= common_q_reg;
211	      common_r_reg <= common_r_reg;
212	    end
213	  end
214	
215	  //finish phase
216	  assign  signed_q  = q_sign_reg ? (~common_q_reg + 1) : common_q_reg;
217	  assign  signed_r  = r_sign_reg ? (~common_r_reg + 1) : common_r_reg;
218	  assign  special_q = div_by_zero_reg ? 32'hffff_ffff : (overflow_reg ? {1'b1,{(`XLEN-1){1'b0}}} : 'd0);
219	  assign  special_r = (div_by_zero_reg | zero_q_reg) ? raw_a_reg : 'd0;
220	
221	  assign  q_o = (div_by_zero_reg | zero_q_reg | overflow_reg) ? special_q : signed_q;
222	  assign  r_o = (div_by_zero_reg | zero_q_reg | overflow_reg) ? special_r : signed_r; 
223	  assign  out_valid_o = current_state == FINISH;
224	  assign  in_ready_o  = current_state == IDLE;
225	
226	  //FSM
227	  always@(*) begin
228	    case(current_state)
229	      IDLE     : begin
230	        if(in_valid_i & in_ready_o) begin
231	          if(overflow | div_by_zero) begin
232	            next_state = FINISH;
233	          end
234	          else begin
235	            next_state = PRE;
236	          end
237	        end
238	        else begin
239	          next_state = IDLE;
240	        end
241	      end
242	
243	      PRE      : begin
244	        if(unsigned_a_reg < unsigned_d_reg) begin
245	          next_state = FINISH;
246	        end
247	        else begin
248	          next_state = COMPUTE;
249	        end
250	      end
251	
252	      COMPUTE  : begin
253	        if(cnt_next != 'd0) begin
254	          next_state = COMPUTE;
255	        end
256	        else begin
257	          next_state = RECOVERY;
258	        end
259	      end
260	
261	      RECOVERY : begin
262	        next_state = FINISH;
263	      end
264	
265	      FINISH   : begin
266	        if(out_ready_i & out_valid_o) begin
267	          next_state = IDLE;
268	        end
269	        else begin
270	          next_state = FINISH;
271	        end
272	      end
273	
274	      default  : next_state = IDLE;
275	    endcase
276	  end
277	
278	  always@(posedge clk or negedge rst_n) begin
279	    if(!rst_n) begin
280	      a_reg <= 'd0;
281	      d_reg <= 'd0;
282	      cnt   <= 'd0;
283	      q     <= 'd0;
284	      qn    <= 'd0;
285	    end
286	    else begin
287	      case(current_state)
288	        IDLE    : begin
289	          a_reg <= 'd0;
290	          d_reg <= 'd0;
291	          cnt   <= 'd0;
292	        end
293	        PRE     : begin
294	          if(unsigned_a_reg < unsigned_d_reg) begin
295	            cnt <= 'd0;
296	          end
297	          else begin
298	            a_reg <= a_norm;
299	            d_reg <= d_norm;
300	            cnt   <= iter  ;
301	            q     <= 'd0   ;
302	            qn    <= 'd0   ;
303	          end
304	        end
305	        COMPUTE : begin
306	          cnt   <= cnt_next;
307	          a_reg <= a_next  ;
308	          q     <= {q[`XLEN-2:0],sel_pos};
309	          qn    <= {qn[`XLEN-2:0],sel_neg};
310	        end
311	        RECOVERY: begin
312	          cnt   <= 'd0     ;
313	        end
314	        FINISH  : begin
315	          cnt   <= 'd0     ;
316	        end
317	        default : begin
318	          a_reg <= 'd0   ;
319	          d_reg <= 'd0   ;
320	          cnt   <= 'd0   ;
321	          q     <= 'd0   ;
322	          qn    <= 'd0   ;
323	        end
324	      endcase
325	    end
326	  end
327	
328	endmodule
